<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { message } from 'ant-design-vue'
import { usePortalStore } from '@/stores/portal'
import { iamMessage } from '@/services/iamAccess'
import { calculationEmployees, previewCalculation, executeCalculation, getEmployeePolicies, saveEmployeePolicy, type CalculationEmployee, type CalculationPreview, type AttendancePolicy } from '@/services/attendanceCalculations'
const portal=usePortalStore(),caps=computed(()=>portal.apps.find(app=>app.id==='attendance')?.accessCapabilities||[])
const options=computed(()=>[{value:'recalculate',label:'重算考勤',op:'attendance.rules.recalculate'},{value:'generate',label:'生成轮班排班',op:'attendance.schedule.generate'}].filter(item=>caps.value.includes(item.op)))
const action=ref('recalculate'),employees=ref<CalculationEmployee[]>([]),selected=ref<string[]>([]),scope=ref(''),start=ref(''),end=ref(''),busy=ref(false),error=ref(''),preview=ref<CalculationPreview|null>(null),command=ref<Record<string,unknown>|null>(null),requestId=ref(''),result=ref<Record<string,unknown>|null>(null)
let run=0
async function search(search=''){const current=++run;employees.value=[];try{const data=await calculationEmployees(action.value,search);if(current!==run)return;employees.value=data.items;scope.value=data.scope}catch(e){if(current===run)error.value=iamMessage(e)}}
async function prepare(){busy.value=true;error.value='';result.value=null;try{const params={action:action.value,employees:JSON.stringify(selected.value),date_from:start.value,date_to:end.value};preview.value=await previewCalculation(params);command.value=params;requestId.value=crypto.randomUUID()}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
async function execute(){if(!command.value||!preview.value||busy.value)return;busy.value=true;error.value='';try{result.value=await executeCalculation({...command.value,expected_inputs:preview.value.expected_inputs,request_id:requestId.value});preview.value=null;message.success('所选范围已完成，未触发外部同步。')}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
const policyOpen=ref(false),policies=ref<AttendancePolicy[]>([]),policyTypes=ref<string[]>([]),editing=ref<AttendancePolicy|null>(null),policyRequest=ref('')
const policy=reactive({policy_type:'ADMIN',effective_from:'',effective_to:'',enabled:true,anchor_shift:'早班',group_name:'',remarks:''})
async function loadPolicies(){if(selected.value.length!==1)return;error.value='';try{const data=await getEmployeePolicies(selected.value[0]!);policies.value=data.items;policyTypes.value=data.policy_types}catch(e){error.value=iamMessage(e)}}
function editPolicy(row?:AttendancePolicy){editing.value=row||null;Object.assign(policy,{policy_type:row?.policy_type||'ADMIN',effective_from:row?.effective_from||'',effective_to:row?.effective_to||'',enabled:row?!!row.enabled:true,anchor_shift:row?.anchor_shift||'早班',group_name:row?.group_name||'',remarks:row?.remarks||''});policyRequest.value=crypto.randomUUID();policyOpen.value=true}
async function savePolicy(){if(selected.value.length!==1||busy.value)return;busy.value=true;error.value='';try{await saveEmployeePolicy({employee:selected.value[0],settings:{...policy,enabled:policy.enabled?1:0,effective_to:policy.effective_to||null},expected_version:editing.value?.modified||'',request_id:policyRequest.value,...(editing.value?{name:editing.value.name}:{})});policyOpen.value=false;await loadPolicies();message.success('规则配置已保存；考勤结果需另行预览重算。')}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
watch(action,()=>{selected.value=[];preview.value=null;void search()})
watch(selected,()=>{policies.value=[];preview.value=null})
onMounted(()=>{action.value=options.value[0]?.value||'manage';void search()})
</script>
<template><section class="rules product-page app-product-page"><header class="glass-hero"><h1>规则与重算</h1><p>{{scope}} · 按员工和日期核对来源，再确认计算。人工、更正和导入排班优先。</p></header><section class="glass-surface section-panel"><a-alert v-if="error" type="warning" :message="error" show-icon/><a-space wrap><a-select v-if="options.length" v-model:value="action" :options="options" aria-label="计算操作" style="min-width:180px"/><a-select v-model:value="selected" mode="multiple" show-search :filter-option="false" :options="employees.map(row=>({value:row.name,label:row.employee_name+' · '+row.employee_number}))" aria-label="计算员工" placeholder="搜索并明确选择员工" style="min-width:320px" @search="search"/><a-input v-model:value="start" type="date" aria-label="计算开始日期"/><a-input v-model:value="end" type="date" aria-label="计算结束日期"/><a-button v-if="options.length" type="primary" :loading="busy" :disabled="!selected.length||!start||!end" @click="prepare">预览计算范围</a-button></a-space><a-alert v-if="result" type="success" message="所选范围计算完成" :description="`出勤配对 ${result.paired_present||0}；缺勤 ${Number(result.paired_absent||0)+Number(result.zero_absent||0)}；请假 ${result.leave_absent||0}；排班生成 ${result.generated||0}；保留已有排班 ${result.protected||0}。`"/></section><section v-if="caps.includes('attendance.rules.manage')" class="glass-surface section-panel"><h2>员工考勤规则</h2><p>选择一名员工后读取配置。生效日期、轮转锚点与启用状态沿用现有原生校验。</p><a-space><a-button :disabled="selected.length!==1" @click="loadPolicies">读取所选员工规则</a-button><a-button :disabled="selected.length!==1" @click="editPolicy()">新增规则配置</a-button></a-space><a-table :data-source="policies" row-key="name"><a-table-column title="策略类型" data-index="policy_type"/><a-table-column title="生效日期" data-index="effective_from"/><a-table-column title="失效日期" data-index="effective_to"/><a-table-column title="状态"><template #default="{record}">{{record.enabled?'启用':'停用'}}</template></a-table-column><a-table-column title="修改"><template #default="{record}"><a-button @click="editPolicy(record)">修改配置</a-button></template></a-table-column></a-table></section><a-modal :open="!!preview" :get-container="false" title="确认计算范围" ok-text="确认执行" cancel-text="返回核对" :confirm-loading="busy" @ok="execute" @cancel="preview=null"><p>{{preview?.scope}}</p><p>{{preview?.date_from}} 至 {{preview?.date_to}} · {{preview?.employees.map(row=>row.employee_name).join('、')}}</p><p>{{preview?.warning}}</p><a-alert v-if="error" type="warning" :message="error"/></a-modal><a-modal v-model:open="policyOpen" :get-container="false" title="员工考勤规则" ok-text="保存配置" cancel-text="取消" :confirm-loading="busy" @ok="savePolicy"><a-alert v-if="error" type="warning" :message="error"/><a-form layout="vertical"><a-form-item label="策略类型"><a-select v-model:value="policy.policy_type" :options="policyTypes.map(value=>({value,label:value}))"/></a-form-item><a-form-item label="生效 / 失效日期"><a-space><a-input v-model:value="policy.effective_from" type="date"/><a-input v-model:value="policy.effective_to" type="date"/></a-space></a-form-item><a-form-item v-if="policy.policy_type==='ROTATION_3DAY'" label="轮转锚点班次"><a-select v-model:value="policy.anchor_shift" :options="['早班','晚班','休息'].map(value=>({value,label:value}))"/><a-input v-model:value="policy.group_name" placeholder="轮转组"/></a-form-item><a-form-item label="事实说明"><a-textarea v-model:value="policy.remarks" :maxlength="500"/></a-form-item><a-checkbox v-model:checked="policy.enabled">启用</a-checkbox></a-form></a-modal></section></template>
<style scoped>.rules{display:grid;gap:20px}.glass-hero,.section-panel{padding:24px}.ant-alert{margin:16px 0}.ant-table-wrapper{margin-top:20px}</style>
